USE vehicle_rental; CREATE OR REPLACE VIEW vehicle_availability AS SELECT v.vehicle_id, v.registration_number, v.make, v.model, v.vehicle_type, v.daily_rate, CASE WHEN v.operational_status <> 'available' THEN v.operational_status WHEN EXISTS ( SELECT 1 FROM bookings b WHERE b.vehicle_id = v.vehicle_id AND b.booking_status = 'active' AND CURDATE() BETWEEN b.start_date AND b.end_date ) THEN 'rented' WHEN EXISTS ( SELECT 1 FROM bookings b WHERE b.vehicle_id = v.vehicle_id AND b.booking_status = 'reserved' AND CURDATE() BETWEEN b.start_date AND b.end_date ) THEN 'reserved' ELSE 'available' END AS availability_status FROM vehicles v;
